python3 - <<'PY'
import json, sys, tomllib
from pathlib import Path
p = Path("bunapp")
problems = []
try:
    biome = json.loads((p / "biome.json").read_text())
    base = json.loads((p / "tsconfig.base.json").read_text())
    ts = json.loads((p / "tsconfig.json").read_text())
    bunfig = tomllib.loads((p / "bunfig.toml").read_text())
except (OSError, ValueError) as e:
    sys.exit(f"missing or invalid config: {e}")
glob = biome.get("files", {}).get("includes", [""])[0]
if "css" not in glob or "html" not in glob:
    problems.append(f"biome includes glob lacks css/html: {glob}")
keys = biome.get("linter", {}).get("rules", {}).get("complexity", {}).get("useLiteralKeys")
if keys not in ("off", {"level": "off"}):
    problems.append(f"useLiteralKeys is {keys!r}, expected off")
opts = base.get("compilerOptions", {})
for key, want in {"module": "preserve", "moduleResolution": "bundler", "strict": True,
                  "noUncheckedIndexedAccess": True, "types": ["bun", "node"]}.items():
    if opts.get(key) != want:
        problems.append(f"tsconfig.base.json {key}={opts.get(key)!r}, expected {want!r}")
for key in ("skipLibCheck", "baseUrl", "composite"):
    if key in opts:
        problems.append(f"tsconfig.base.json sets {key}")
if ts.get("extends") != "./tsconfig.base.json":
    problems.append(f"tsconfig.json extends {ts.get('extends')!r}")
inc = " ".join(ts.get("include", []))
if "src" not in inc or "tests" not in inc:
    problems.append(f"tsconfig.json include misses src or tests: {inc}")
if bunfig.get("install", {}).get("linker") != "isolated":
    problems.append("bunfig.toml [install] linker is not isolated")
print("\n".join(problems) or "config matches the baseline")
sys.exit(1 if problems else 0)
PY
